CREATE TABLE IF NOT EXISTS "catalog_products" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The marketplace-wide code every seller lists against. Sellers do not own it, which is the single decision the whole marketplace rests on.
	"product_code" VARCHAR(20) NOT NULL UNIQUE,
	-- Variation parent, e.g. the shirt whose children are the sizes. Null for a standalone product.
	"parent_id" BIGINT,
	-- Manufacturer barcode when one exists. Used to match a new listing onto an existing catalogue entry rather than creating a duplicate.
	"gtin" VARCHAR(14),
	-- Brand name. Null for unbranded goods, which are a large share of the long tail.
	"brand" VARCHAR(160),
	-- Canonical title. Owned by the marketplace, not the seller, so a seller cannot keyword-stuff the shared page.
	"title" VARCHAR(500) NOT NULL,
	-- Normalised facets such as colour or capacity, used for filtering. A document because the attribute set differs wildly per category.
	"attributes" JSONB NOT NULL DEFAULT '''{}''',
	-- Materialised browse path such as electronics/audio/headphones. Stored flat because it is read on every page and changed almost never.
	"category_path" VARCHAR(300) NOT NULL,
	-- When the catalogue entry was first created, by whichever seller got there first.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "catalog_products" IS 'One row per distinct product in the world, not per listing. Twelve sellers of the same pair of headphones share this row, which is what makes one review set and one buy box possible.';
COMMENT ON COLUMN "catalog_products"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "catalog_products"."product_code" IS 'The marketplace-wide code every seller lists against. Sellers do not own it, which is the single decision the whole marketplace rests on.';
COMMENT ON COLUMN "catalog_products"."parent_id" IS 'Variation parent, e.g. the shirt whose children are the sizes. Null for a standalone product.';
COMMENT ON COLUMN "catalog_products"."gtin" IS 'Manufacturer barcode when one exists. Used to match a new listing onto an existing catalogue entry rather than creating a duplicate.';
COMMENT ON COLUMN "catalog_products"."brand" IS 'Brand name. Null for unbranded goods, which are a large share of the long tail.';
COMMENT ON COLUMN "catalog_products"."title" IS 'Canonical title. Owned by the marketplace, not the seller, so a seller cannot keyword-stuff the shared page.';
COMMENT ON COLUMN "catalog_products"."attributes" IS 'Normalised facets such as colour or capacity, used for filtering. A document because the attribute set differs wildly per category.';
COMMENT ON COLUMN "catalog_products"."category_path" IS 'Materialised browse path such as electronics/audio/headphones. Stored flat because it is read on every page and changed almost never.';
COMMENT ON COLUMN "catalog_products"."created_at" IS 'When the catalogue entry was first created, by whichever seller got there first.';

CREATE INDEX "idx_catalog_parent"
ON "catalog_products" ("parent_id");
CREATE INDEX "idx_catalog_category"
ON "catalog_products" ("category_path");

CREATE TABLE IF NOT EXISTS "sellers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Storefront name shown next to an offer. Distinct from the legal name, which buyers rarely recognise.
	"display_name" VARCHAR(200) NOT NULL,
	-- Registered business name, shown on invoices and required for marketplace liability rules.
	"legal_name" VARCHAR(200) NOT NULL,
	-- ISO 3166-1 alpha-2 country of the business. Drives tax withholding and which marketplaces the seller may list on.
	"country_code" CHAR(2) NOT NULL,
	-- pending | active | suspended | terminated. Suspension hides every offer without deleting price history.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Rolling seller rating from 0 to 1. Null until enough orders exist to be meaningful; a default of 1 would flatter new sellers into the buy box.
	"feedback_score" NUMERIC(4,3),
	-- Share of orders shipped after the promised date. A direct input to the buy box decision.
	"late_shipment_rate" NUMERIC(5,4) NOT NULL DEFAULT 0,
	-- Days a payout is withheld after delivery. Higher for new or risky sellers, which is why it lives per seller.
	"payout_hold_days" INTEGER NOT NULL DEFAULT 14,
	-- When the seller was approved.
	"onboarded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sellers" IS 'A third-party merchant. Sellers never own catalogue rows - they own offers - so removing a seller cannot take a product page down with it.';
COMMENT ON COLUMN "sellers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sellers"."display_name" IS 'Storefront name shown next to an offer. Distinct from the legal name, which buyers rarely recognise.';
COMMENT ON COLUMN "sellers"."legal_name" IS 'Registered business name, shown on invoices and required for marketplace liability rules.';
COMMENT ON COLUMN "sellers"."country_code" IS 'ISO 3166-1 alpha-2 country of the business. Drives tax withholding and which marketplaces the seller may list on.';
COMMENT ON COLUMN "sellers"."status" IS 'pending | active | suspended | terminated. Suspension hides every offer without deleting price history.';
COMMENT ON COLUMN "sellers"."feedback_score" IS 'Rolling seller rating from 0 to 1. Null until enough orders exist to be meaningful; a default of 1 would flatter new sellers into the buy box.';
COMMENT ON COLUMN "sellers"."late_shipment_rate" IS 'Share of orders shipped after the promised date. A direct input to the buy box decision.';
COMMENT ON COLUMN "sellers"."payout_hold_days" IS 'Days a payout is withheld after delivery. Higher for new or risky sellers, which is why it lives per seller.';
COMMENT ON COLUMN "sellers"."onboarded_at" IS 'When the seller was approved.';

CREATE TABLE IF NOT EXISTS "offers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Product being offered. Many offers point at the same row; that competition is the marketplace.
	"catalog_product_id" BIGINT NOT NULL,
	-- Seller making the offer.
	"seller_id" BIGINT NOT NULL,
	-- new | refurbished | used_like_new | used_good | used_acceptable. Part of the identity of an offer: one seller may list the same product twice in two conditions.
	"condition" VARCHAR(16) NOT NULL DEFAULT 'new',
	-- Offer price in minor units, excluding shipping. Integers only - never float money.
	"price_cents" INTEGER NOT NULL,
	-- Shipping charged. The buy box compares landed price, so this cannot be ignored.
	"shipping_cents" INTEGER NOT NULL DEFAULT 0,
	-- ISO 4217 currency for the price columns.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Units the seller can ship. Zero makes the offer ineligible for the buy box but leaves it visible.
	"quantity_available" INTEGER NOT NULL DEFAULT 0,
	-- seller | platform. Platform-fulfilled offers ship from marketplace warehouses and win ties on delivery speed.
	"fulfillment_channel" VARCHAR(16) NOT NULL DEFAULT 'seller',
	-- Days between order and handover to the carrier. Combined with the carrier estimate to promise a delivery date.
	"handling_days" INTEGER NOT NULL DEFAULT 2,
	-- Seller-controlled pause. Separate from quantity so going on holiday does not look like a stockout.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Last price or stock change. Repricing bots touch this constantly, so it is the hot column on the table.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "offers" IS 'One seller selling one product in one condition. This is the row a price is attached to; the catalogue row has no price at all, and could not sensibly have one.';
COMMENT ON COLUMN "offers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "offers"."catalog_product_id" IS 'Product being offered. Many offers point at the same row; that competition is the marketplace.';
COMMENT ON COLUMN "offers"."seller_id" IS 'Seller making the offer.';
COMMENT ON COLUMN "offers"."condition" IS 'new | refurbished | used_like_new | used_good | used_acceptable. Part of the identity of an offer: one seller may list the same product twice in two conditions.';
COMMENT ON COLUMN "offers"."price_cents" IS 'Offer price in minor units, excluding shipping. Integers only - never float money.';
COMMENT ON COLUMN "offers"."shipping_cents" IS 'Shipping charged. The buy box compares landed price, so this cannot be ignored.';
COMMENT ON COLUMN "offers"."currency_code" IS 'ISO 4217 currency for the price columns.';
COMMENT ON COLUMN "offers"."quantity_available" IS 'Units the seller can ship. Zero makes the offer ineligible for the buy box but leaves it visible.';
COMMENT ON COLUMN "offers"."fulfillment_channel" IS 'seller | platform. Platform-fulfilled offers ship from marketplace warehouses and win ties on delivery speed.';
COMMENT ON COLUMN "offers"."handling_days" IS 'Days between order and handover to the carrier. Combined with the carrier estimate to promise a delivery date.';
COMMENT ON COLUMN "offers"."is_active" IS 'Seller-controlled pause. Separate from quantity so going on holiday does not look like a stockout.';
COMMENT ON COLUMN "offers"."updated_at" IS 'Last price or stock change. Repricing bots touch this constantly, so it is the hot column on the table.';

CREATE UNIQUE INDEX "uq_offers_seller_product_condition"
ON "offers" ("seller_id", "catalog_product_id", "condition");
CREATE INDEX "idx_offers_product_active_price"
ON "offers" ("catalog_product_id", "is_active", "price_cents");

CREATE TABLE IF NOT EXISTS "buy_box_awards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Product whose buy box was awarded.
	"catalog_product_id" BIGINT NOT NULL,
	-- Winning offer.
	"offer_id" BIGINT NOT NULL,
	-- Composite score at decision time, from landed price, seller metrics and delivery speed. Stored so a seller dispute can be answered with the actual numbers.
	"score" NUMERIC(6,4) NOT NULL,
	-- Price plus shipping that won. Snapshotted because the offer will have been repriced many times since.
	"landed_price_cents" INTEGER NOT NULL,
	-- Dominant factor such as lowest_landed, faster_delivery or sole_eligible. What seller support quotes back.
	"reason" VARCHAR(40) NOT NULL,
	-- When this offer took the box.
	"won_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it lost the box. Null means this is the current winner, which is the only query the product page runs.
	"lost_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "buy_box_awards" IS 'The buy box as an append-only decision log rather than a winner column on the product. Rotation is constant, and without the history nobody can explain why a seller stopped selling.';
COMMENT ON COLUMN "buy_box_awards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "buy_box_awards"."catalog_product_id" IS 'Product whose buy box was awarded.';
COMMENT ON COLUMN "buy_box_awards"."offer_id" IS 'Winning offer.';
COMMENT ON COLUMN "buy_box_awards"."score" IS 'Composite score at decision time, from landed price, seller metrics and delivery speed. Stored so a seller dispute can be answered with the actual numbers.';
COMMENT ON COLUMN "buy_box_awards"."landed_price_cents" IS 'Price plus shipping that won. Snapshotted because the offer will have been repriced many times since.';
COMMENT ON COLUMN "buy_box_awards"."reason" IS 'Dominant factor such as lowest_landed, faster_delivery or sole_eligible. What seller support quotes back.';
COMMENT ON COLUMN "buy_box_awards"."won_at" IS 'When this offer took the box.';
COMMENT ON COLUMN "buy_box_awards"."lost_at" IS 'When it lost the box. Null means this is the current winner, which is the only query the product page runs.';

CREATE INDEX "idx_buybox_product_current"
ON "buy_box_awards" ("catalog_product_id", "lost_at");
CREATE INDEX "idx_buybox_offer_won"
ON "buy_box_awards" ("offer_id", "won_at");

CREATE TABLE IF NOT EXISTS "buyers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity, held by the marketplace. Sellers never see it, which is why orders snapshot a separate contact field.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name.
	"full_name" VARCHAR(160) NOT NULL,
	-- Current default delivery address. Orders snapshot their own copy, so editing this cannot rewrite where a parcel went.
	"default_address" JSONB,
	-- Membership flag. It changes which offers are eligible and which delivery promise is shown.
	"prime_member" BOOLEAN NOT NULL DEFAULT false,
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "buyers" IS 'The marketplace customer. One buyer relationship, however many sellers end up involved in a single checkout.';
COMMENT ON COLUMN "buyers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "buyers"."email" IS 'Login identity, held by the marketplace. Sellers never see it, which is why orders snapshot a separate contact field.';
COMMENT ON COLUMN "buyers"."full_name" IS 'Display name.';
COMMENT ON COLUMN "buyers"."default_address" IS 'Current default delivery address. Orders snapshot their own copy, so editing this cannot rewrite where a parcel went.';
COMMENT ON COLUMN "buyers"."prime_member" IS 'Membership flag. It changes which offers are eligible and which delivery promise is shown.';
COMMENT ON COLUMN "buyers"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Customer who checked out.
	"buyer_id" BIGINT NOT NULL,
	-- Human-facing reference. One per checkout, which is the number the buyer quotes even when five sellers were involved.
	"order_number" VARCHAR(32) NOT NULL UNIQUE,
	-- Currency the totals are denominated in.
	"currency_code" CHAR(3) NOT NULL,
	-- Sum of all sub-order item totals.
	"items_total_cents" INTEGER NOT NULL,
	-- Total shipping across every sub-order.
	"shipping_total_cents" INTEGER NOT NULL DEFAULT 0,
	-- Total tax. Collected by the marketplace, which is the facilitator in most jurisdictions.
	"tax_total_cents" INTEGER NOT NULL DEFAULT 0,
	-- Single amount authorised against the payment method. The buyer sees one charge.
	"grand_total_cents" INTEGER NOT NULL,
	-- Delivery address snapshot, shared by every sub-order in this checkout.
	"shipping_address" JSONB NOT NULL,
	-- Gateway charge id. Unique so a replayed webhook cannot double-record the money.
	"payment_reference" VARCHAR(120) UNIQUE,
	-- Checkout completion time.
	"placed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'The buyer-facing order: one payment, one address, one confirmation email. It deliberately holds no line items - those belong to a seller.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."buyer_id" IS 'Customer who checked out.';
COMMENT ON COLUMN "orders"."order_number" IS 'Human-facing reference. One per checkout, which is the number the buyer quotes even when five sellers were involved.';
COMMENT ON COLUMN "orders"."currency_code" IS 'Currency the totals are denominated in.';
COMMENT ON COLUMN "orders"."items_total_cents" IS 'Sum of all sub-order item totals.';
COMMENT ON COLUMN "orders"."shipping_total_cents" IS 'Total shipping across every sub-order.';
COMMENT ON COLUMN "orders"."tax_total_cents" IS 'Total tax. Collected by the marketplace, which is the facilitator in most jurisdictions.';
COMMENT ON COLUMN "orders"."grand_total_cents" IS 'Single amount authorised against the payment method. The buyer sees one charge.';
COMMENT ON COLUMN "orders"."shipping_address" IS 'Delivery address snapshot, shared by every sub-order in this checkout.';
COMMENT ON COLUMN "orders"."payment_reference" IS 'Gateway charge id. Unique so a replayed webhook cannot double-record the money.';
COMMENT ON COLUMN "orders"."placed_at" IS 'Checkout completion time.';

CREATE INDEX "idx_orders_buyer_placed"
ON "orders" ("buyer_id", "placed_at");

CREATE TABLE IF NOT EXISTS "seller_orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent checkout.
	"order_id" BIGINT NOT NULL,
	-- Seller responsible for this part of the order.
	"seller_id" BIGINT NOT NULL,
	-- seller | platform. Frozen at purchase, because who shipped it decides who is liable when it does not arrive.
	"fulfillment_channel" VARCHAR(16) NOT NULL,
	-- pending | acknowledged | shipped | delivered | cancelled | refunded. Each seller moves through this independently.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Sum of this sub-order line totals. The base for the referral fee.
	"items_total_cents" INTEGER NOT NULL,
	-- Shipping attributed to this seller.
	"shipping_cents" INTEGER NOT NULL DEFAULT 0,
	-- Marketplace commission, computed at purchase and frozen so a later rate change cannot rewrite what was owed.
	"referral_fee_cents" INTEGER NOT NULL DEFAULT 0,
	-- Pick, pack and ship fee. Zero for a seller-fulfilled sub-order.
	"fulfillment_fee_cents" INTEGER NOT NULL DEFAULT 0,
	-- Promised handover date. Missing it is what feeds sellers.late_shipment_rate.
	"ship_by_date" DATE NOT NULL,
	-- Set when this seller part is cancelled. The rest of the checkout is unaffected.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "seller_orders" IS 'The unit of fulfilment, invoicing and cancellation. Splitting here is what lets one seller ship tomorrow and another refund, without either touching the buyer payment.';
COMMENT ON COLUMN "seller_orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "seller_orders"."order_id" IS 'Parent checkout.';
COMMENT ON COLUMN "seller_orders"."seller_id" IS 'Seller responsible for this part of the order.';
COMMENT ON COLUMN "seller_orders"."fulfillment_channel" IS 'seller | platform. Frozen at purchase, because who shipped it decides who is liable when it does not arrive.';
COMMENT ON COLUMN "seller_orders"."status" IS 'pending | acknowledged | shipped | delivered | cancelled | refunded. Each seller moves through this independently.';
COMMENT ON COLUMN "seller_orders"."items_total_cents" IS 'Sum of this sub-order line totals. The base for the referral fee.';
COMMENT ON COLUMN "seller_orders"."shipping_cents" IS 'Shipping attributed to this seller.';
COMMENT ON COLUMN "seller_orders"."referral_fee_cents" IS 'Marketplace commission, computed at purchase and frozen so a later rate change cannot rewrite what was owed.';
COMMENT ON COLUMN "seller_orders"."fulfillment_fee_cents" IS 'Pick, pack and ship fee. Zero for a seller-fulfilled sub-order.';
COMMENT ON COLUMN "seller_orders"."ship_by_date" IS 'Promised handover date. Missing it is what feeds sellers.late_shipment_rate.';
COMMENT ON COLUMN "seller_orders"."cancelled_at" IS 'Set when this seller part is cancelled. The rest of the checkout is unaffected.';

CREATE INDEX "idx_seller_orders_seller_status"
ON "seller_orders" ("seller_id", "status");
CREATE INDEX "idx_seller_orders_order"
ON "seller_orders" ("order_id");

CREATE TABLE IF NOT EXISTS "seller_order_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent sub-order.
	"seller_order_id" BIGINT NOT NULL,
	-- Offer sold. Nullable so a seller may delete an offer without destroying order history.
	"offer_id" BIGINT,
	-- Product sold, kept independently of the offer so analytics survive offer deletion.
	"catalog_product_id" BIGINT,
	-- Catalogue code snapshot, the join key that still works after either row above is gone.
	"product_code" VARCHAR(20) NOT NULL,
	-- Product title exactly as shown at purchase, since the shared catalogue title can be rewritten by anyone.
	"title" VARCHAR(500) NOT NULL,
	-- Condition snapshot. A used-good purchase must not later read as new because the seller relisted.
	"condition" VARCHAR(16) NOT NULL,
	-- Units bought.
	"quantity" INTEGER NOT NULL,
	-- Price per unit at purchase. Never re-read from the offer, which reprices several times an hour.
	"unit_price_cents" INTEGER NOT NULL,
	-- quantity * unit_price_cents, stored so line arithmetic is auditable.
	"total_cents" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "seller_order_items" IS 'Immutable lines. Everything a receipt and a dispute need is snapshotted, because on a marketplace the catalogue text is not controlled by the person who sold you the thing.';
COMMENT ON COLUMN "seller_order_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "seller_order_items"."seller_order_id" IS 'Parent sub-order.';
COMMENT ON COLUMN "seller_order_items"."offer_id" IS 'Offer sold. Nullable so a seller may delete an offer without destroying order history.';
COMMENT ON COLUMN "seller_order_items"."catalog_product_id" IS 'Product sold, kept independently of the offer so analytics survive offer deletion.';
COMMENT ON COLUMN "seller_order_items"."product_code" IS 'Catalogue code snapshot, the join key that still works after either row above is gone.';
COMMENT ON COLUMN "seller_order_items"."title" IS 'Product title exactly as shown at purchase, since the shared catalogue title can be rewritten by anyone.';
COMMENT ON COLUMN "seller_order_items"."condition" IS 'Condition snapshot. A used-good purchase must not later read as new because the seller relisted.';
COMMENT ON COLUMN "seller_order_items"."quantity" IS 'Units bought.';
COMMENT ON COLUMN "seller_order_items"."unit_price_cents" IS 'Price per unit at purchase. Never re-read from the offer, which reprices several times an hour.';
COMMENT ON COLUMN "seller_order_items"."total_cents" IS 'quantity * unit_price_cents, stored so line arithmetic is auditable.';

CREATE INDEX "idx_soi_seller_order"
ON "seller_order_items" ("seller_order_id");
CREATE INDEX "idx_soi_product"
ON "seller_order_items" ("catalog_product_id");

CREATE TABLE IF NOT EXISTS "shipments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Sub-order being shipped.
	"seller_order_id" BIGINT NOT NULL,
	-- seller | platform. Determines who owns the tracking dispute and whose metrics the delay counts against.
	"shipped_by" VARCHAR(16) NOT NULL,
	-- Marketplace fulfilment centre code. Null for a seller-fulfilled parcel, where the origin is the seller address.
	"origin_warehouse" VARCHAR(60),
	-- Carrier name.
	"carrier" VARCHAR(60) NOT NULL,
	-- Carrier tracking number once assigned. Null between shipping confirmation and label scan.
	"tracking_number" VARCHAR(80),
	-- Delivery date shown to the buyer at checkout. The measure late delivery is judged against.
	"promised_by" DATE NOT NULL,
	-- Handover to the carrier.
	"shipped_at" TIMESTAMPTZ,
	-- Confirmed delivery. Starts the payout hold clock on this sub-order.
	"delivered_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipments" IS 'A parcel, attached to the sub-order rather than the order. One sub-order can produce several when stock is split across warehouses.';
COMMENT ON COLUMN "shipments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipments"."seller_order_id" IS 'Sub-order being shipped.';
COMMENT ON COLUMN "shipments"."shipped_by" IS 'seller | platform. Determines who owns the tracking dispute and whose metrics the delay counts against.';
COMMENT ON COLUMN "shipments"."origin_warehouse" IS 'Marketplace fulfilment centre code. Null for a seller-fulfilled parcel, where the origin is the seller address.';
COMMENT ON COLUMN "shipments"."carrier" IS 'Carrier name.';
COMMENT ON COLUMN "shipments"."tracking_number" IS 'Carrier tracking number once assigned. Null between shipping confirmation and label scan.';
COMMENT ON COLUMN "shipments"."promised_by" IS 'Delivery date shown to the buyer at checkout. The measure late delivery is judged against.';
COMMENT ON COLUMN "shipments"."shipped_at" IS 'Handover to the carrier.';
COMMENT ON COLUMN "shipments"."delivered_at" IS 'Confirmed delivery. Starts the payout hold clock on this sub-order.';

CREATE INDEX "idx_shipments_seller_order"
ON "shipments" ("seller_order_id");
CREATE INDEX "idx_shipments_tracking"
ON "shipments" ("tracking_number");

CREATE TABLE IF NOT EXISTS "payouts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Seller being paid.
	"seller_id" BIGINT NOT NULL,
	-- First day of the settlement window.
	"period_start" DATE NOT NULL,
	-- Last day of the settlement window, inclusive.
	"period_end" DATE NOT NULL,
	-- Sum of item and shipping revenue in the window, before any deduction.
	"gross_cents" INTEGER NOT NULL,
	-- Total referral and fulfilment fees deducted. Always the sum of the entry rows, never entered by hand.
	"fees_cents" INTEGER NOT NULL,
	-- Refunds, chargebacks and goodwill, which routinely make a window negative.
	"adjustments_cents" INTEGER NOT NULL DEFAULT 0,
	-- Amount actually transferred. gross - fees + adjustments, stored so a bank transfer can be reconciled against one number.
	"net_cents" INTEGER NOT NULL,
	-- Currency of the transfer.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | released | paid | failed | withheld. Withheld covers open A-to-Z claims.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- When the transfer left. Null while pending.
	"paid_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payouts" IS 'A settlement window per seller, not a payment per order. Sellers are paid in batches on a hold schedule, so the batch is the thing that needs an identity.';
COMMENT ON COLUMN "payouts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payouts"."seller_id" IS 'Seller being paid.';
COMMENT ON COLUMN "payouts"."period_start" IS 'First day of the settlement window.';
COMMENT ON COLUMN "payouts"."period_end" IS 'Last day of the settlement window, inclusive.';
COMMENT ON COLUMN "payouts"."gross_cents" IS 'Sum of item and shipping revenue in the window, before any deduction.';
COMMENT ON COLUMN "payouts"."fees_cents" IS 'Total referral and fulfilment fees deducted. Always the sum of the entry rows, never entered by hand.';
COMMENT ON COLUMN "payouts"."adjustments_cents" IS 'Refunds, chargebacks and goodwill, which routinely make a window negative.';
COMMENT ON COLUMN "payouts"."net_cents" IS 'Amount actually transferred. gross - fees + adjustments, stored so a bank transfer can be reconciled against one number.';
COMMENT ON COLUMN "payouts"."currency_code" IS 'Currency of the transfer.';
COMMENT ON COLUMN "payouts"."status" IS 'pending | released | paid | failed | withheld. Withheld covers open A-to-Z claims.';
COMMENT ON COLUMN "payouts"."paid_at" IS 'When the transfer left. Null while pending.';

CREATE UNIQUE INDEX "uq_payouts_seller_period"
ON "payouts" ("seller_id", "period_start");

CREATE TABLE IF NOT EXISTS "payout_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Settlement batch this entry belongs to.
	"payout_id" BIGINT NOT NULL,
	-- Sub-order the money relates to. Null for an entry with no order behind it, such as a monthly subscription fee.
	"seller_order_id" BIGINT,
	-- sale | referral_fee | fulfillment_fee | refund | chargeback | adjustment.
	"entry_type" VARCHAR(24) NOT NULL,
	-- Signed amount in minor units. Negative for anything the marketplace takes back.
	"amount_cents" INTEGER NOT NULL,
	-- Human explanation shown in the seller statement. What stops a support ticket.
	"description" VARCHAR(200),
	-- When the underlying event happened, which is often in an earlier window than the payout.
	"occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payout_entries" IS 'The line-by-line statement. Sellers dispute payouts constantly, and a single net number with no entries behind it is unanswerable.';
COMMENT ON COLUMN "payout_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payout_entries"."payout_id" IS 'Settlement batch this entry belongs to.';
COMMENT ON COLUMN "payout_entries"."seller_order_id" IS 'Sub-order the money relates to. Null for an entry with no order behind it, such as a monthly subscription fee.';
COMMENT ON COLUMN "payout_entries"."entry_type" IS 'sale | referral_fee | fulfillment_fee | refund | chargeback | adjustment.';
COMMENT ON COLUMN "payout_entries"."amount_cents" IS 'Signed amount in minor units. Negative for anything the marketplace takes back.';
COMMENT ON COLUMN "payout_entries"."description" IS 'Human explanation shown in the seller statement. What stops a support ticket.';
COMMENT ON COLUMN "payout_entries"."occurred_at" IS 'When the underlying event happened, which is often in an earlier window than the payout.';

CREATE INDEX "idx_payout_entries_payout_type"
ON "payout_entries" ("payout_id", "entry_type");
CREATE INDEX "idx_payout_entries_seller_order"
ON "payout_entries" ("seller_order_id");

CREATE TABLE IF NOT EXISTS "reviews" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Product reviewed. Attached to the catalogue row, not to the seller, so every offer of the same product shares one review set.
	"catalog_product_id" BIGINT NOT NULL,
	-- Reviewer.
	"buyer_id" BIGINT NOT NULL,
	-- Purchase that justifies the review. Null for an unverified review, which is exactly what verified_purchase encodes.
	"seller_order_item_id" BIGINT,
	-- One to five stars.
	"rating" SMALLINT NOT NULL,
	-- Review headline.
	"title" VARCHAR(200),
	-- Review text. Null for a rating-only review, which is most of them.
	"body" TEXT,
	-- True when seller_order_item_id is set and delivery was confirmed. Denormalised because it is filtered on constantly.
	"verified_purchase" BOOLEAN NOT NULL DEFAULT false,
	-- Reader votes, used for sorting.
	"helpful_votes" INTEGER NOT NULL DEFAULT 0,
	-- published | held | removed. Held is a classifier decision awaiting a human, typically for incentivised-review patterns.
	"status" VARCHAR(16) NOT NULL DEFAULT 'published',
	-- Submission time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "reviews" IS 'Reviews of the product, not of the seller. Seller performance lives on sellers as metrics instead, because a buyer complaining about a slow parcel is not rating the headphones.';
COMMENT ON COLUMN "reviews"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "reviews"."catalog_product_id" IS 'Product reviewed. Attached to the catalogue row, not to the seller, so every offer of the same product shares one review set.';
COMMENT ON COLUMN "reviews"."buyer_id" IS 'Reviewer.';
COMMENT ON COLUMN "reviews"."seller_order_item_id" IS 'Purchase that justifies the review. Null for an unverified review, which is exactly what verified_purchase encodes.';
COMMENT ON COLUMN "reviews"."rating" IS 'One to five stars.';
COMMENT ON COLUMN "reviews"."title" IS 'Review headline.';
COMMENT ON COLUMN "reviews"."body" IS 'Review text. Null for a rating-only review, which is most of them.';
COMMENT ON COLUMN "reviews"."verified_purchase" IS 'True when seller_order_item_id is set and delivery was confirmed. Denormalised because it is filtered on constantly.';
COMMENT ON COLUMN "reviews"."helpful_votes" IS 'Reader votes, used for sorting.';
COMMENT ON COLUMN "reviews"."status" IS 'published | held | removed. Held is a classifier decision awaiting a human, typically for incentivised-review patterns.';
COMMENT ON COLUMN "reviews"."created_at" IS 'Submission time.';

CREATE INDEX "idx_reviews_product_status_created"
ON "reviews" ("catalog_product_id", "status", "created_at");
CREATE UNIQUE INDEX "uq_reviews_buyer_item"
ON "reviews" ("buyer_id", "seller_order_item_id");

